import{c as a,Q as e,j as n,m as l}from"./chunks/framework.DOi4mjdC.js";const s="/assets/%E5%8F%82%E6%95%B0%E8%A7%A3%E6%9E%90%E7%A4%BA%E6%84%8F%E5%9B%BE.C23eoCk0.png",u=JSON.parse('{"title":"切片数据搬运","description":"","frontmatter":{},"headers":[{"level":1,"title":"切片数据搬运","slug":"切片数据搬运"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"支持的通路和数据类型","slug":"支持的通路和数据类型"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory数据搬运/DataCopy/切片数据搬运.md","filePath":"api/SIMD-API/基础API/Memory数据搬运/DataCopy/切片数据搬运.md"}'),o={name:"api/SIMD-API/基础API/Memory数据搬运/DataCopy/切片数据搬运.md"};function d(i,t,r,p,c,h){return e(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="切片数据搬运" tabindex="-1">切片数据搬运 <a class="header-anchor" href="#切片数据搬运" aria-label="Permalink to &quot;切片数据搬运&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>支持数据的切片搬运，提取多维Tensor数据的子集进行搬运。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>Global Memory -&gt; Local Memory</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>\n<span class="line"><span>__aicore__ inline void DataCopy(const LocalTensor&lt;T&gt;&amp; dst, const GlobalTensor&lt;T&gt;&amp; src, const SliceInfo dstSliceInfo[], const SliceInfo srcSliceInfo[], const uint32_t dimValue = 1)</span></span></code></pre></div></li><li><p>Local Memory -&gt; Global Memory</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>\n<span class="line"><span>__aicore__ inline void DataCopy(const GlobalTensor&lt;T&gt; &amp;dst, const LocalTensor&lt;T&gt; &amp;src, const SliceInfo dstSliceInfo[], const SliceInfo srcSliceInfo[], const uint32_t dimValue = 1)</span></span></code></pre></div></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>各原型支持的具体数据通路和数据类型，请参考<a href="#section186352046151419">支持的通路和数据类型</a>。</p></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>源操作数和目的操作数的数据类型。支持的数据类型请参考支持的通路和数据类型。</td></tr></tbody></table><p><strong>表 2</strong> 切片数据搬运接口参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor或GlobalTensor。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor或GlobalTensor。</td></tr><tr><td>srcSliceInfo/dstSliceInfo</td><td>输入</td><td>目的操作数/源操作数切片信息，SliceInfo类型。 具体定义请参考${INSTALL_DIR}/include/ascendc/basic_api/interface/kernel_struct_data_copy.h，${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。</td></tr><tr><td>dimValue</td><td>输入</td><td>操作数维度信息，默认值为1。</td></tr></tbody></table><p><strong>表 3</strong> SliceInfo结构参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>startIndex</td><td>切片的起始元素位置。</td></tr><tr><td>endIndex</td><td>切片的终止元素位置。</td></tr><tr><td>stride</td><td>切片的间隔元素个数。</td></tr><tr><td>burstLen</td><td>横向切片，每一片数据的长度，仅在维度为1时生效，超出1维的情况下，必须配置为1，不支持配置成其他值。单位为datablock（32B）。比如，srcSliceInfo的List为 <span>{{16, 70, 7, 3, 87}, {0, 2, 1, 1, 3}}</span>，{16, 70, 7, 3, 87}表示第一维的切片信息，burstLen设置为3，表示一个切片数据段大小为3个datablock； {0, 2, 1, 1, 3}为第二维的切片信息，burstLen仅能设置为1。</td></tr><tr><td>shapeValue</td><td>当前维度的原始长度。单位为元素个数。</td></tr></tbody></table><p>通过具体的示例对上述参数进行解析，示意图如下：</p><p><strong>图 1</strong> 参数解析示意图<br><img src="'+s+`" alt="" title="参数解析示意图"></p><ul><li><p>dimValue为2，表示操作数有2维。</p></li><li><p>srcSliceInfo为 <span>{{16, 70, 7, 3, 87}, {0, 2, 1, 1, 3}}</span></p><ul><li><p>{16, 70, 7, 3, 87}是针对单独一行， 即从一维的角度来配置，每个元素代表一个数：</p><p><strong>startIndex</strong> = 16，表示有效数据段从第16个数开始；</p><p><strong>endIndex</strong> = 70，表示有效数据段到第70个数结束；</p><p><strong>stride</strong> = 7，单位为元素个数，表示相邻的2个切片数据段间隔的元素个数，为7个0的间距；</p><p><strong>burstLen</strong> = 3，单位为32B，表示在这一个有效数据段中，一个切片数据段大小为3个datablock；</p><p><strong>shapeValue</strong> = 87，表示单独一行的长度，单位为元素个数，即 8 * 10 + 7 = 87个元素。</p></li><li><p>{0, 2, 1, 1, 3}是针对多行，即从二维的角度来配置，每个元素代表一行：</p><p><strong>startIndex</strong> = 0，表示有效数据段从第0行开始；</p><p><strong>endIndex</strong> = 2，表示有效数据段到第2行结束；</p><p><strong>stride</strong> = 1，表示相邻的2个切片数据段中间隔元素为1行；</p><p><strong>burstLen</strong> = 1，在dimValue &gt; 1时必须填为1；</p><p><strong>shapeValue</strong> = 3，表明一共有3行。</p></li></ul></li><li><p>dstSliceInfo为<span>{{0, 47, 0, 3, 48}, {0, 1, 0, 1, 2}}</span></p><ul><li><p>{0, 47, 0, 3, 48}是针对单独一行， 即从一维的角度来配置，每个元素代表一个数：</p><p><strong>startIndex</strong> = 0，表示有效数据段从第0个数开始；</p><p><strong>endIndex</strong> = 47，表示有效数据段到第47个数结束；</p><p><strong>stride</strong> = 0，单位为元素个数，表示相邻的2个切片数据段间隔的元素个数，为0表示两个切片数据段没有间距；</p><p><strong>burstLen</strong> = 3，单位为32B，表示在这一个有效数据段中，一个切片数据段大小为3个datablock；</p><p><strong>shapeValue</strong> = 48，表示单独一行的长度，单位为元素个数，即8 * 6 = 48个元素。</p></li><li><p>{0, 1, 0, 1, 2} 是针对多行，即从二维的角度来配置，每个元素代表1行：</p><p>**startIndex **= 0，表示有效数据段从第0行开始；</p><p>**endIndex **= 1，表示有效数据段到第1行结束；</p><p>**stride **= 0，表示相邻的2个切片数据段没有间隔；</p><p><strong>burstLen</strong> = 1，在dimValue &gt; 1时必须填为1；</p><p>**shapeValue **= 2，表示一共有2行。</p></li></ul></li></ul><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>切片数据搬运中的横向burstLen大小设置，需要用户自己通过计算：横向切片元素个数* sizeof(T)/32byte。横向切片元素个数* sizeof(T)的大小必须是32byte的倍数。</li><li>切片数据搬运中的SliceInfo结构体数组大小和dimValue需要保持一致，并且不超过8。</li><li>切片数据搬运中的srcSliceInfo数组大小的和dstSliceInfo的大小需要保持一致，两者的结构体中的burstLen需要相等（srcSliceInfo[i].burstLen = dstSliceInfo[i].burstLen）。</li><li>切片数据搬运对参数有一定要求，建议使用者参考调用示例，并在CPU上仿真结果无误后，再到NPU侧执行。</li></ul><h2 id="支持的通路和数据类型" tabindex="-1">支持的通路和数据类型 <a class="header-anchor" href="#支持的通路和数据类型" aria-label="Permalink to &quot;支持的通路和数据类型&quot;">​</a></h2><p>下文的数据通路均通过逻辑位置<a href="./../../../其他数据类型/TPosition.html#table5376122715308">TPosition</a>来表达，并注明了对应的物理通路。TPosition与物理内存的映射关系见<a href="./../../../通用说明和约束.html#table07372185712">表1</a>。</p><p><strong>表 4</strong> Global Memory -&gt; Local Memory具体通路和支持的数据类型</p><table tabindex="0"><thead><tr><th>产品型号</th><th>数据通路</th><th>源操作数和目的操作数的数据类型（两者保持一致）</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>GM -&gt; VECIN（GM -&gt; UB）</td><td>bool、int8_t、uint8_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、fp8_e8m0_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、complex32、int64_t、uint64_t、double、complex64</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>GM -&gt; VECIN（GM -&gt; UB）</td><td>int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、half、float</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>GM -&gt; VECIN（GM -&gt; UB）</td><td>int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、half、bfloat16_t、float</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>GM -&gt; VECIN（GM -&gt; UB）</td><td>int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、half、bfloat16_t、float</td></tr></tbody></table><p><strong>表 5</strong> Local Memory -&gt; Global Memory具体通路和支持的数据类型</p><table tabindex="0"><thead><tr><th>产品型号</th><th>数据通路</th><th>源操作数和目的操作数的数据类型（两者保持一致）</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>VECOUT -&gt; GM（UB -&gt; GM）</td><td>bool、int8_t、uint8_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、fp8_e8m0_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、complex32、int64_t、uint64_t、double、complex64</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>VECOUT、CO2 -&gt; GM（UB -&gt; GM）</td><td>int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、half、float</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>VECOUT -&gt; GM（UB -&gt; GM）</td><td>int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、half、bfloat16_t、float</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>VECOUT -&gt; GM（UB -&gt; GM）</td><td>int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、half、bfloat16_t、float</td></tr></tbody></table><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本示例仅展示样例中的部分代码。如需运行，请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/00_data_movement/data_copy_gm2ub_slice" target="_blank" rel="noreferrer">切片数据搬运样例</a>实现完整的代码。srcSliceInfo、dstSliceInfo参数解析与结果示例请参考<a href="#fig1196816115710">图1</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// srcLocal为float类型的LocalTensor，srcGlobal、dstGlobal为float类型的GlobalTensor</span></span>
<span class="line"><span>uint32_t dimValue = 2; // 操作数维度为2</span></span>
<span class="line"><span>AscendC::SliceInfo srcSliceInfo[] = {{16, 70, 7, 3, 87}, {0, 2, 1, 1, 3}};</span></span>
<span class="line"><span>AscendC::SliceInfo dstSliceInfo[] = {{0, 47, 0, 3, 48}, {0, 1, 0, 1, 2}};</span></span>
<span class="line"><span>// Global Memory -&gt; Local Memory</span></span>
<span class="line"><span>AscendC::DataCopy(srcLocal, srcGlobal,  dstSliceInfo, srcSliceInfo, dimValue);</span></span>
<span class="line"><span>// Local Memory -&gt; Global Memory</span></span>
<span class="line"><span>AscendC::DataCopy(dstGlobal, srcLocal, dstSliceInfo, dstSliceInfo, dimValue);</span></span></code></pre></div>`,31)])])}const b=a(o,[["render",d]]);export{u as __pageData,b as default};
